"""Run the workspace's command the way the task's interface describes."""

import json
import os
import subprocess
import sys

COMMAND = "stay"
PATH = os.path.join(os.environ["WARRANT_WORKSPACE"], COMMAND)


def call(request=None, raw=None, timeout=10):
    """Send a request (or raw text) on stdin. Returns (exit status, parsed JSON output or None)."""
    if not os.access(PATH, os.X_OK):
        sys.exit(f"the workspace has no executable named stay")
    text = raw if raw is not None else json.dumps(request)
    try:
        done = subprocess.run([PATH], input=text, capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return 124, None
    output = done.stdout.strip()
    if not output:
        return done.returncode, None
    try:
        return done.returncode, json.loads(output)
    except json.JSONDecodeError:
        return done.returncode, output


def finish(problems, summary):
    if problems:
        shown = problems if len(problems) <= 12 else problems[:10] + [f"...and {len(problems) - 10} more"]
        print("\n".join(shown))
        sys.exit(1)
    print(summary)

"""P1: the stay command's interface."""

from _cmd import call, finish

FIELDS = {"room_cents", "discount_cents", "tax_cents", "total_cents"}
problems = []

status, body = call({"check_in": "tue", "nights": 4, "rate_cents": 9900})
if status != 0:
    problems.append(f"a valid request should exit 0, got status {status}")
if not isinstance(body, dict):
    problems.append(f"a valid request should print one JSON object, got {body!r}")
elif set(body) != FIELDS:
    problems.append(f"the response should have exactly the fields {sorted(FIELDS)}, got {sorted(body)}")
elif not all(type(body[field]) is int for field in FIELDS):
    problems.append(f"every amount should be a whole number of cents, got {body!r}")

for label, request, raw in [
    ("0 nights", {"check_in": "tue", "nights": 0, "rate_cents": 9900}, None),
    ("text that is not JSON", None, "two nights please"),
]:
    status, body = call(request, raw=raw)
    if status != 2 or body is not None:
        problems.append(f"{label}: should be refused with status 2 and nothing on standard output, got status {status} and {body!r}")

finish(problems, "contract ok")

"""P3: one-night stays on each weekday."""

from _cmd import call, finish

EXPECTED_TOTAL = {"sun": 20275, "mon": 20275, "tue": 20275, "wed": 20275, "thu": 20275, "fri": 25275}
problems = []
for day, total in EXPECTED_TOTAL.items():
    status, body = call({"check_in": day, "nights": 1, "rate_cents": 20000})
    charged = body.get("total_cents") if isinstance(body, dict) else None
    if status != 0 or charged != total:
        problems.append(f"one {day} night at 20000: expected a total of {total}, got {charged!r} (status {status})")

status, body = call({"check_in": "sat", "nights": 1, "rate_cents": 20000})
if status == 0 or (isinstance(body, dict) and "total_cents" in body):
    problems.append(f"one sat night should be refused, got {body!r} (status {status})")

finish(problems, "one-night stays ok")

